// ---- helpers ----

export function componentsForScreen(screenId) {
  return COMPONENTS.filter(c => c.screen === screenId);
}

export function getScreen(screenId) {
  return SCREENS.find(s => s.id === screenId) || null;
}

export function getComponentById(cmpId) {
  return COMPONENTS.find(c => c.id === cmpId) || null;
}

export function getStandard(stdId) {
  return STANDARDS.find(s => s.id === stdId) || null;
}

// Access codes in the sheet: 'X' (no access), 'R' (read), 'R/U' (read+update),
// 'C/R/U/D' (full CRUD). '-' / empty treated as no access.
export function canAccess(accessCode) {
  const code = String(accessCode || '').trim().toUpperCase();
  if (!code || code === 'X' || code === '-') return 'hidden';
  if (code === 'R') return 'readonly';
  return 'interactive'; // R/U, C/R/U/D
}

export function accessForRole(cmpOrScreen, roleId) {
  return canAccess(cmpOrScreen?.access?.[roleId]);
}

// Effective interaction mode for a COMPONENT: the sheet encodes interactivity in
// BOTH the access code and the Editabile column — e.g. CMP-48 "Acknowledge allarme"
// is OL=R but Editabile=Y (the OL must be able to ack). So:
//   X/-                       -> 'hidden'
//   contains U/C/D            -> 'interactive'
//   R with Editabile=Y        -> 'interactive'
//   R with Editabile=N        -> 'readonly'
export function effectiveMode(component, roleId) {
  const base = canAccess(component?.access?.[roleId]);
  if (base !== 'readonly') return base;
  return component?.editabile === 'Y' ? 'interactive' : 'readonly';
}

